-- Backfill verification_date/verified_by (set by an admin seeded user)
UPDATE vendors SET
    verification_date = COALESCE(verification_date, created_at),
    verified_by = COALESCE(verified_by, (SELECT id FROM users WHERE email = 'admin@burncost.com' LIMIT 1)),
    transaction_volume = COALESCE(transaction_volume, total_sales),
    updated_at = NOW()
WHERE verification_date IS NULL OR verified_by IS NULL OR transaction_volume IS NULL;

